const e="Grading Policies",t={verified:!1,lastEdited:"9/9/2026",branch:"main",tablesPresent:0,tablesConsumed:0,tablesOnPage:0,tablesExcluded:0,sourceUrl:"https://catalog.northeastern.edu/graduate/science/academic-policies-procedures/grading-policies/",panes:[""],planOfStudyCourses:[],verification:{level:"partial",kind:"grad",score:.83,checkedAt:"2026-09-10",sourceUrl:"https://catalog.northeastern.edu/graduate/science/academic-policies-procedures/grading-policies/",sourcesAvailable:["requirement-tables","course-catalog"],counters:{tablesUnaccounted:0,leakedMarkers:0,unenumeratedSections:1,duplicateSectionTitles:0,duplicateConcentrationTitles:0,zeroTotal:1,unknownCourses:0,planUnexplained:0,impossibleSections:0},discrepancies:[{check:"missing-total-credits",severity:"medium",message:"the catalog page states no total credit requirement",detail:[{key:"noTotal"}],overflow:0},{check:"unenumerated-sections",severity:"info",message:"1 section(s) state a credit requirement whose courses the catalog does not list, so completion of those cannot be checked automatically",detail:[{key:"unenumeratedSection",params:{title:"2026-2027 Edition",sh:6}}],overflow:0}]}},a=0,r=2027,s=[{type:"SECTION",title:"2026-2027 Edition",creditsRequired:6,minRequirementCount:1,requirements:[],notes:["In the College of Science, not more than two courses or 6 semester hours of credit, whichever is greater, may be repeated to satisfy the requirements for the degree. Only such repeats will be counted in calculating the cumulative grade-point average.","No grade changes are permitted after the end of the final examination period one calendar year from the semester in which the student registered for the course. In calculating the overall cumulative average, all graduate-level coursework completed at the time of clearance, regardless of program, will be counted, including other coursework completed for graduate certificates, master’s degrees, doctoral programs, and personal interest or professional development.","Students cannot elect a satisfactory/unsatisfactory grading scheme for College of Science courses, unless the course grading scheme is designated satisfactory/unsatisfactory."]}],o={name:e,metadata:t,totalCreditsRequired:a,yearVersion:r,requirementSections:s};export{o as default,t as metadata,e as name,s as requirementSections,a as totalCreditsRequired,r as yearVersion};
